select NAME,TYPE,LINE,TEXT from USER_ERRORS where NAME not like 'BIN$%'order by NAME,SEQUENCE;
select c.CASE_PICK_TASK_ID,c.CONTENT_VERSION,f.PICKED_CONTENT_VERSION from RRL_CASE_PICK_TASK c join RRL_CUSTOMER_ORDER_FULFILLMENT f on f.PICKED_CASE_TASK_ID=c.CASE_PICK_TASK_ID where f.STATUS='PICKED'and c.CASE_PICK_TASK_ID in(1129,1130);
